37	func show(name string, tree caddyfile.FileTree, want [][]string, wantErr string) error {
38	    bs, err := caddyfile.Parse("Caddyfile", tree["Caddyfile"], tree)
39	    got := flat(bs)
40	    encoded, _ := json.Marshal(got)
41	    if err != nil { fmt.Printf("%s error=%q parsed=%s\n", name, err.Error(), encoded) } else { fmt.Printf("%s parsed=%s\n", name, encoded) }
42	    if wantErr != "" {
43	        if err == nil { return fmt.Errorf("%s: expected error containing %q", name, wantErr) }
44	        if bs != nil { return fmt.Errorf("%s: failed parse returned non-nil blocks", name) }
45	        if !strings.Contains(err.Error(), wantErr) { return fmt.Errorf("%s: error %q lacks %q", name, err.Error(), wantErr) }
46	        return nil
