import os
import subprocess
import sys
import tempfile

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
mode = sys.argv[1] if len(sys.argv) > 1 else "full"
if mode not in ("full", "success", "errors"):
    print("environment/adapter failure: mode must be full, success, or errors", file=sys.stderr)
    raise SystemExit(2)

go = r'''package main

import (
    "encoding/json"
    "fmt"
    "os"
    "reflect"
    "strings"
    "sync"

    "github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

func flat(bs []caddyfile.ServerBlock) [][]string {
    out := [][]string{}
    for _, b := range bs {
        for _, seg := range b.Segments {
            row := []string{}
            for _, tok := range seg { row = append(row, tok.Text) }
            out = append(out, row)
        }
    }
    return out
}

func show(name string, tree caddyfile.FileTree, want [][]string, wantErr string) error {
    bs, err := caddyfile.Parse("Caddyfile", tree["Caddyfile"], tree)
    got := flat(bs)
    encoded, _ := json.Marshal(got)
    if err != nil { fmt.Printf("%s error=%q parsed=%s\n", name, err.Error(), encoded) } else { fmt.Printf("%s parsed=%s\n", name, encoded) }
    if wantErr != "" {
        if err == nil { return fmt.Errorf("%s: expected error containing %q", name, wantErr) }
        if bs != nil { return fmt.Errorf("%s: failed parse returned non-nil blocks", name) }
        if !strings.Contains(err.Error(), wantErr) { return fmt.Errorf("%s: error %q lacks %q", name, err.Error(), wantErr) }
        return nil
    }
    if err != nil { return fmt.Errorf("%s: unexpected error: %v", name, err) }
    if !reflect.DeepEqual(got, want) { return fmt.Errorf("%s: expected %v, got %v", name, want, got) }
    return nil
}

func successCases() error {
    if err := show("args-and-literals", caddyfile.FileTree{
        "Caddyfile": []byte("import f.caddy \\\"hello world\\\" \\\"\\\" \\\"a\\\\\\\"b\\\"\\n"),
        "f.caddy": []byte("a {args[0]}\\nb {args[1]}\\nc {args[2]}\\njoin pre-{args[0]}-post\\nplain {host}\\nescaped \\\\{args[0]\\\\}\\n"),
    }, [][]string{{"a", "hello world"}, {"b", ""}, {"c", "a\\\"b"}, {"join", "pre-hello world-post"}, {"plain", "{host}"}, {"escaped", "{args[0]}"}}, ""); err != nil { return err }
    if err := show("variadic", caddyfile.FileTree{
        "Caddyfile": []byte("import f.caddy one \\\"two words\\\" three\\n"),
        "f.caddy": []byte("all {args[:]}\\ntail {args[1:]}\\nspan {args[0:2]}\\nadj {args[0]}:{args[1]}\\n"),
    }, [][]string{{"all", "one", "two words", "three"}, {"tail", "two words", "three"}, {"span", "one", "two words"}, {"adj", "one:two words"}}, ""); err != nil { return err }
    if err := show("separator-normalization", caddyfile.FileTree{
        "Caddyfile": []byte("import sub/f.caddy\\n"),
        "sub\\\\f.caddy": []byte("separator value\\n"),
    }, [][]string{{"separator", "value"}}, ""); err != nil { return err }
    if err := show("glob-order-and-repeat", caddyfile.FileTree{
        "Caddyfile": []byte("import conf/*.caddy\\nimport conf/a.caddy\\n"),
        "conf/b.caddy": []byte("from-b\\n"), "conf/a.caddy": []byte("from-a\\n"), "conf/.hidden.caddy": []byte("hidden\\n"),
    }, [][]string{{"from-a"}, {"from-b"}, {"from-a"}}, ""); err != nil { return err }
    return nil
}

func errorCases() error {
    if err := show("scope-without-redeclaration", caddyfile.FileTree{
        "Caddyfile": []byte("import outer.caddy outer-value\\n"),
        "outer.caddy": []byte("import inner.caddy\\n"), "inner.caddy": []byte("inner {args[0]}\\n"),
    }, nil, "inner.caddy:1"); err != nil { return err }
    if err := show("invalid-index", caddyfile.FileTree{
        "Caddyfile": []byte("import bad.caddy x\\n"), "bad.caddy": []byte("d {args[x]}\\n"),
    }, nil, "invalid argument"); err != nil { return err }
    if err := show("embedded-variadic", caddyfile.FileTree{
        "Caddyfile": []byte("import bad.caddy x\\n"), "bad.caddy": []byte("d pre-{args[:]}-post\\n"),
    }, nil, "must be a token on its own"); err != nil { return err }
    if err := show("unclosed-quote", caddyfile.FileTree{
        "Caddyfile": []byte("respond \\\"never closed"),
    }, nil, "unclosed quote"); err != nil { return err }
    if err := show("missing-target", caddyfile.FileTree{
        "Caddyfile": []byte("import missing.caddy\\n"),
    }, nil, "missing.caddy"); err != nil { return err }
    return nil
}

func isolationCase() error {
    var wg sync.WaitGroup
    errs := make(chan error, 8)
    for i := 0; i < 8; i++ {
        wg.Add(1)
        go func(i int) {
            defer wg.Done()
            value := fmt.Sprintf("worker-%d", i)
            tree := caddyfile.FileTree{"Caddyfile": []byte("import f.caddy\\n"), "f.caddy": []byte("value " + value + "\\n")}
            bs, err := caddyfile.Parse("Caddyfile", tree["Caddyfile"], tree)
            got := flat(bs)
            encoded, _ := json.Marshal(got)
            fmt.Printf("parallel-%d parsed=%s\n", i, encoded)
            if err != nil { errs <- err; return }
            if len(got) != 1 || len(got[0]) != 2 || got[0][1] != value { errs <- fmt.Errorf("parallel-%d observed %v", i, got) }
        }(i)
    }
    wg.Wait(); close(errs)
    for err := range errs { return err }
    return nil
}

func main() {
    mode := "full"
    if len(os.Args) > 1 { mode = os.Args[1] }
    var err error
    switch mode {
    case "success": err = successCases()
    case "errors": err = errorCases()
    default:
        err = successCases()
        if err == nil { err = errorCases() }
        if err == nil { err = isolationCase() }
    }
    if err != nil { fmt.Fprintln(os.Stderr, "product assertion failure:", err); os.Exit(1) }
}
'''

fd, path = tempfile.mkstemp(prefix="cc_import_accept_", suffix=".go", dir=root)
os.close(fd)
try:
    with open(path, "w", encoding="utf-8") as f:
        f.write(go)
    proc = subprocess.run(["go", "run", path, mode], cwd=root, text=True, capture_output=True)
    if proc.stdout:
        print(proc.stdout, end="")
    if proc.stderr:
        print(proc.stderr, end="", file=sys.stderr)
    if proc.returncode != 0:
        raise SystemExit(proc.returncode)
finally:
