27		"github.com/caddyserver/caddy/v2"
28	)
29	
30	// Parse parses the input just enough to group tokens, in
31	// order, by server block. No further parsing is performed.
32	// Server blocks are returned in the order in which they appear.
33	// Directives that do not appear in validDirectives will cause
34	// an error. If you do not want to check for valid directives,
35	// pass in nil instead.
36	//
37	// Environment variables in {$ENVIRONMENT_VARIABLE} notation
38	// will be replaced before parsing begins.
39	//
40	// If a FileTree is provided, every file named by an import
41	// directive is read from that in-memory snapshot rather than
42	// from disk: the tree is the sole source of imported contents
43	// for the call, so replacing files on disk between calls can
44	// never mix versions into the result. When no tree is given,
45	// imports resolve on the operating system filesystem as
46	// before. Parse keeps no state between calls: argument
47	// expansions, caches, and errors from one parse can never be
48	// observed by another, even when calls run concurrently.
49	func Parse(filename string, input []byte, fileTree ...FileTree) ([]ServerBlock, error) {
50		// unfortunately, we must copy the input because parsing must
51		// remain a read-only operation, but we have to expand environment
52		// variables before we parse, which changes the underlying array (#4422)
53		inputCopy := make([]byte, len(input))
54		copy(inputCopy, input)
55	
56		tokens, err := allTokens(filename, inputCopy)
57		if err != nil {
58			return nil, err
59		}
60	
61		var tree FileTree
62		if len(fileTree) > 0 {
63			tree = fileTree[0]
64		}
65	
66		p := parser{
67			Dispenser: NewDispenser(tokens),
68			imports:   openImportSource(tree),
69			importGraph: importGraph{
70				nodes: make(map[string]struct{}),
71				edges: make(adjacency),
72			},
73		}
74		blocks, err := p.parseAll()
75		if err != nil {
76			// never hand back a partially-expanded block list: a
77			// failed parse must not be usable as configuration
78			return nil, err
79		}
80		return blocks, nil
81	}
82	
83	// allTokens lexes the entire input, but does not parse it.
84	// It returns all the tokens from the input, unstructured
85	// and in order. It may mutate input as it expands env vars.
86	// Unclosed quotes are rejected because the resulting token
87	// stream would be ambiguous about where arguments end.
88	func allTokens(filename string, input []byte) ([]Token, error) {
89		return tokenizeStrict(replaceEnvVars(input), filename)
90	}
91	
92	// replaceEnvVars replaces all occurrences of environment variables.
93	// It mutates the underlying array and returns the updated slice.
94	func replaceEnvVars(input []byte) []byte {
95		var offset int
96		for {
97			begin := bytes.Index(input[offset:], spanOpen)
98			if begin < 0 {
99				break
100			}
101			begin += offset // make beginning relative to input, not offset
102			end := bytes.Index(input[begin+len(spanOpen):], spanClose)
103			if end < 0 {
104				break
105			}
106			end += begin + len(spanOpen) // make end relative to input, not begin
107	
108			// get the name; if there is no name, skip it
109			envString := input[begin+len(spanOpen) : end]
110			if len(envString) == 0 {
111				offset = end + len(spanClose)
112				continue
113			}
114	
115			// split the string into a key and an optional default
116			envParts := strings.SplitN(string(envString), envVarDefaultDelimiter, 2)
117	
118			// do a lookup for the env var, replace with the default if not found
119			envVarValue, found := os.LookupEnv(envParts[0])
120			if !found && len(envParts) == 2 {
121				envVarValue = envParts[1]
122			}
123	
124			// get the value of the environment variable
125			// note that this causes one-level deep chaining
126			envVarBytes := []byte(envVarValue)
127	
128			// splice in the value
129			input = append(input[:begin],
130				append(envVarBytes, input[end+len(spanClose):]...)...)
131	
132			// continue at the end of the replacement
133			offset = begin + len(envVarBytes)
134		}
135		return input
136	}
137	
138	type parser struct {
139		*Dispenser
140		block           ServerBlock // current server block being parsed
141		eof             bool        // if we encounter a valid EOF in a hard place
142		definedSnippets map[string][]Token
143		nesting         int
144		imports         importSource
145		importGraph     importGraph
146	}
147	
148	func (p *parser) parseAll() ([]ServerBlock, error) {
149		var blocks []ServerBlock
150	
151		for p.Next() {
152			err := p.parseOne()
153			if err != nil {
154				return blocks, err
155			}
156			if len(p.block.Keys) > 0 || len(p.block.Segments) > 0 {
157				blocks = append(blocks, p.block)
158			}
159			if p.nesting > 0 {
160				return blocks, p.EOFErr()
161			}
162		}
163	
164		return blocks, nil
165	}
166	
167	func (p *parser) parseOne() error {
168		p.block = ServerBlock{}
169		return p.begin()
170	}
171	
172	func (p *parser) begin() error {
173		if len(p.tokens) == 0 {
174			return nil
175		}
176	
177		err := p.addresses()
178		if err != nil {
179			return err
180		}
181	
182		if p.eof {
183			// this happens if the Caddyfile consists of only
184			// a line of addresses and nothing else
185			return nil
186		}
187	
188		if ok, name := p.isNamedRoute(); ok {
189			// we just need a dummy leading token to ease parsing later
190			nameToken := p.Token()
191			nameToken.Text = name
192	
193			// named routes only have one key, the route name
194			p.block.Keys = []Token{nameToken}
195			p.block.IsNamedRoute = true
196	
197			// get all the tokens from the block, including the braces
198			tokens, err := p.blockTokens(true)
199			if err != nil {
200				return err
201			}
202			tokens = append([]Token{nameToken}, tokens...)
203			p.block.Segments = []Segment{tokens}
204			return nil
205		}
206	
207		if ok, name := p.isSnippet(); ok {
208			if p.definedSnippets == nil {
209				p.definedSnippets = map[string][]Token{}
210			}
211			if _, found := p.definedSnippets[name]; found {
212				return p.Errf("redeclaration of previously declared snippet %s", name)
213			}
214			// consume all tokens til matched close brace
215			tokens, err := p.blockTokens(false)
216			if err != nil {
217				return err
218			}
219			// Just as we need to track which file the token comes from, we need to
220			// keep track of which snippet the token comes from. This is helpful
221			// in tracking import cycles across files/snippets by namespacing them.
222			// Without this, we end up with false-positives in cycle-detection.
223			for k, v := range tokens {
224				v.snippetName = name
225				tokens[k] = v
226			}
227			p.definedSnippets[name] = tokens
228			// empty block keys so we don't save this block as a real server.
229			p.block.Keys = nil
230			return nil
231		}
232	
233		return p.blockContents()
234	}
235	
236	func (p *parser) addresses() error {
237		var expectingAnother bool
238	
239		for {
240			value := p.Val()
241			token := p.Token()
242	
243			// Reject request matchers if trying to define them globally
244			if strings.HasPrefix(value, "@") {
245				return p.Errf("request matchers may not be defined globally, they must be in a site block; found %s", value)
246			}
247	
248			// Special case: import directive replaces tokens during parse-time
249			if value == "import" && p.isNewLine() {
250				err := p.doImport(0)
251				if err != nil {
252					return err
253				}
254				continue
255			}
256	
257			// Open brace definitely indicates end of addresses
258			if value == "{" {
259				if expectingAnother {
260					return p.Errf("Expected another address but had '%s' - check for extra comma", value)
261				}
262				// Mark this server block as being defined with braces.
263				// This is used to provide a better error message when
264				// the user may have tried to define two server blocks
265				// without having used braces, which are required in
266				// that case.
267				p.block.HasBraces = true
268				break
269			}
270	
271			// Users commonly forget to place a space between the address and the '{'
272			if strings.HasSuffix(value, "{") {
273				return p.Errf("Site addresses cannot end with a curly brace: '%s' - put a space between the token and the brace", value)
274			}
275	
276			if value != "" { // empty token possible if user typed ""
277				// Trailing comma indicates another address will follow, which
278				// may possibly be on the next line
279				if value[len(value)-1] == ',' {
280					value = value[:len(value)-1]
281					expectingAnother = true
282				} else {
283					expectingAnother = false // but we may still see another one on this line
284				}
285	
286				// If there's a comma here, it's probably because they didn't use a space
287				// between their two domains, e.g. "foo.com,bar.com", which would not be
288				// parsed as two separate site addresses.
289				if strings.Contains(value, ",") {
290					return p.Errf("Site addresses cannot contain a comma ',': '%s' - put a space after the comma to separate site addresses", value)
291				}
292	
293				// After the above, a comma surrounded by spaces would result
294				// in an empty token which we should ignore
295				if value != "" {
296					// Add the token as a site address
297					token.Text = value
298					p.block.Keys = append(p.block.Keys, token)
299				}
300			}
301	
302			// Advance token and possibly break out of loop or return error
303			hasNext := p.Next()
304			if expectingAnother && !hasNext {
305				return p.EOFErr()
306			}
307			if !hasNext {
308				p.eof = true
309				break // EOF
310			}
311			if !expectingAnother && p.isNewLine() {
312				break
313			}
314		}
315	
316		return nil
317	}
318	
319	func (p *parser) blockContents() error {
320		errOpenCurlyBrace := p.openCurlyBrace()
321		if errOpenCurlyBrace != nil {
322			// single-server configs don't need curly braces
323			p.cursor--
324		}
325	
326		err := p.directives()
327		if err != nil {
328			return err
329		}
330	
331		// only look for close curly brace if there was an opening
332		if errOpenCurlyBrace == nil {
333			err = p.closeCurlyBrace()
334			if err != nil {
335				return err
336			}
337		}
338	
339		return nil
340	}
341	
342	// directives parses through all the lines for directives
343	// and it expects the next token to be the first
344	// directive. It goes until EOF or closing curly brace
345	// which ends the server block.
346	func (p *parser) directives() error {
347		for p.Next() {
348			// end of server block
349			if p.Val() == "}" {
350				// p.nesting has already been decremented
351				break
352			}
353	
354			// special case: import directive replaces tokens during parse-time
355			if p.Val() == "import" {
356				err := p.doImport(1)
357				if err != nil {
358					return err
359				}
360				p.cursor-- // cursor is advanced when we continue, so roll back one more
361				continue
362			}
363	
364			// normal case: parse a directive as a new segment
365			// (a "segment" is a line which starts with a directive
366			// and which ends at the end of the line or at the end of
367			// the block that is opened at the end of the line)
368			if err := p.directive(); err != nil {
369				return err
370			}
371		}
372	
373		return nil
374	}
375	
376	// doImport swaps out the import directive and its argument
377	// (a total of 2 tokens) with the tokens in the specified file
378	// or globbing pattern. When the function returns, the cursor
379	// points at the first imported token, which sits exactly where
380	// the import directive used to.
381	func (p *parser) doImport(nesting int) error {
382		// remember where the import statement started, so the splice
383		// never depends on how many argument or block tokens were read
384		importStart := p.cursor
385	
386		// syntax checks
387		if !p.NextArg() {
388			return p.ArgErr()
389		}
390		importPattern := p.Val()
391		if importPattern == "" {
392			return p.Err("Import requires a non-empty filepath")
393		}
394	
395		// grab remaining args as full tokens so that arguments keep
396		// their exact bytes and quoting: empty arguments, spaces, and
397		// quotes must never be re-tokenized during expansion
398		argTokens := p.RemainingArgsAsTokens()
399	
400		// grab all the tokens (if it exists) from within a block that follows the import
401		var blockTokens []Token
402		for currentNesting := p.Nesting(); p.NextBlock(currentNesting); {
403			blockTokens = append(blockTokens, p.Token())
404		}
405		// initialize with size 1
406		blockMapping := make(map[string][]Token, 1)
407		if len(blockTokens) > 0 {
408			// use such tokens to create a new dispenser, and then use it to parse each block
409			bd := NewDispenser(blockTokens)
410	
411			// one iteration processes one sub-block inside the import
412			for bd.Next() {
413				currentMappingKey := bd.Val()
414	
415				if currentMappingKey == "{" {
416					return p.Err("anonymous blocks are not supported")
417				}
418	
419				// load up all arguments (if there even are any)
420				currentMappingTokens := bd.RemainingArgsAsTokens()
421	
422				// load up the entire block
423				for mappingNesting := bd.Nesting(); bd.NextBlock(mappingNesting); {
424					currentMappingTokens = append(currentMappingTokens, bd.Token())
425				}
426	
427				blockMapping[currentMappingKey] = currentMappingTokens
428			}
429		}
430	
431		// everything before the import statement stays exactly where it was
432		tokensBefore := p.tokens[:importStart]
433		tokensAfter := p.tokens[p.cursor+1:]
434		var importedTokens []Token
435		var nodes []string
436	
437		// first check snippets. That is a simple, non-recursive replacement
438		if p.definedSnippets != nil && p.definedSnippets[importPattern] != nil {
439			// deep-copy the stored definition so repeated imports, and the
440			// annotations appended below, can never mutate one another or
441			// the snippet table (see the same-file, different-branch case)
442			stored := p.definedSnippets[importPattern]
443			importedTokens = make([]Token, len(stored))
444			for i := range stored {
445				importedTokens[i] = stored[i].Clone()
446			}
447			if len(importedTokens) > 0 {
448				// just grab the first one
449				nodes = append(nodes, fmt.Sprintf("%s:%s", importedTokens[0].File, importedTokens[0].snippetName))
450			}
451		} else {
452			fileTokens, fileNodes, err := p.resolveFileImports(importPattern)
453			if err != nil {
454				return err
455			}
456			importedTokens = fileTokens
457			nodes = fileNodes
458		}
459	
460		nodeName := p.File()
461		if p.Token().snippetName != "" {
462			nodeName += fmt.Sprintf(":%s", p.Token().snippetName)
463		}
464		p.importGraph.addNode(nodeName)
465		p.importGraph.addNodes(nodes)
466		if err := p.importGraph.addEdges(nodeName, nodes); err != nil {
467			p.importGraph.removeNodes(nodes)
468			return err
469		}
470	
471		tokensCopy := make([]Token, 0, len(importedTokens))
472	
473		var (
474			maybeSnippet   bool
475			maybeSnippetId bool
476			index          int
477		)
478	
479		// Expand argument placeholders for this one layer only: only the
480		// arguments given to THIS import statement are visible among these
481		// tokens. A nested import reached from within (a named snippet or
482		// another file) is expanded later, when the parser reaches the
483		// nested statement, with that layer's own arguments in scope, so
484		// values passed by an outer layer never leak across layers.
485		//
486		// golang for range slice return a copy of value
487		// similarly, append also copy value
488		for i, token := range importedTokens {
489			// update the token's imports to refer to import directive filename, line number and snippet name if there is one
490			if token.snippetName != "" {
491				token.imports = append(token.imports, fmt.Sprintf("%s:%d (import %s)", p.File(), p.Line(), token.snippetName))
492			} else {
493				token.imports = append(token.imports, fmt.Sprintf("%s:%d (import)", p.File(), p.Line()))
494			}
495	
496			// naive way of determine snippets, as snippets definition can only follow name + block
497			// format, won't check for nesting correctness or any other error, that's what parser does.
498			if !maybeSnippet && nesting == 0 {
499				// first of the line
500				if i == 0 || isNextOnNewLine(tokensCopy[len(tokensCopy)-1], token) {
501					index = 0
502				} else {
503					index++
504				}
505	
506				if index == 0 && len(token.Text) >= 3 && strings.HasPrefix(token.Text, "(") && strings.HasSuffix(token.Text, ")") {
507					maybeSnippetId = true
508				}
509			}
510	
511			switch token.Text {
512			case "{":
513				nesting++
514				if index == 1 && maybeSnippetId && nesting == 1 {
515					maybeSnippet = true
516					maybeSnippetId = false
517				}
518			case "}":
519				nesting--
520				if nesting == 0 && maybeSnippet {
521					maybeSnippet = false
522				}
523			}
524			// if it is {block}, we substitute with all tokens in the block
525			// if it is {blocks.*}, we substitute with the tokens in the mapping for the *
526			var blockTokensToAdd []Token
527			foundBlockDirective := false
528			switch {
529			case token.Text == "{block}":
530				foundBlockDirective = true
531				blockTokensToAdd = blockTokens
532			case strings.HasPrefix(token.Text, "{blocks.") && strings.HasSuffix(token.Text, "}"):
533				foundBlockDirective = true
534				// {blocks.foo.bar} will be extracted to key `foo.bar`
535				blockKey := strings.TrimPrefix(strings.TrimSuffix(token.Text, "}"), "{blocks.")
536				val, ok := blockMapping[blockKey]
537				if ok {
538					blockTokensToAdd = val
539				}
540			}
541	
542			if foundBlockDirective {
543				if maybeSnippet {
544					tokensCopy = append(tokensCopy, token)
545				} else {
546					tokensCopy = append(tokensCopy, blockTokensToAdd...)
547				}
548				continue
549			}
550	
551			if maybeSnippet {
552				// placeholders inside a snippet definition are not
553				// expanded until the snippet itself is imported
554				tokensCopy = append(tokensCopy, token)
555				continue
556			}
557	
558			replaced, err := substituteImportArgs(token, argTokens)
559			if err != nil {
560				return err
561			}
562			tokensCopy = append(tokensCopy, replaced...)
563		}
564	
565		// splice the imported tokens in the place of the import statement;
566		// the cursor lands on the first imported token so parsing simply
567		// continues into the expansion
568		p.tokens = append(tokensBefore, append(tokensCopy, tokensAfter...)...)
569		p.cursor = importStart
570	
571		return nil
572	}
573	
574	// resolveFileImports turns the import pattern into the tokens of
575	// every matching file, reading from the configured FileTree when one
576	// was given or from disk otherwise.
577	func (p *parser) resolveFileImports(importPattern string) ([]Token, []string, error) {
578		if tree, ok := p.imports.(normalizedTree); ok {
579			return p.resolveTreeImports(tree, importPattern)
580		}
581		return p.resolveDiskImports(importPattern)
582	}
583	
584	// resolveTreeImports resolves an import pattern entirely inside the
585	// in-memory FileTree snapshot.
586	func (p *parser) resolveTreeImports(tree normalizedTree, importPattern string) ([]Token, []string, error) {
587		importingFile := normalizeTreePath(p.Dispenser.File())
588		globPattern, err := resolveImportPath(importingFile, importPattern)
589		if err != nil {
590			return nil, nil, p.Errf("%v", err)
591		}
592	
593		hasMeta := strings.ContainsAny(globPattern, "*?[")
594		var matches []string
595		if hasMeta {
596			// bound pathological patterns just like the on-disk path
597			// (issue #2096)
598			if strings.Count(globPattern, "*") > 1 || strings.Count(globPattern, "?") > 1 ||
599				(strings.Contains(globPattern, "[") && strings.Contains(globPattern, "]")) {
600				return nil, nil, p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
601			}
602			matches, err = tree.globPattern(globPattern)
603			if err != nil {
604				return nil, nil, p.Errf("Failed to use import pattern %s: %v", importPattern, err)
605			}
606		} else {
607			matches = []string{globPattern}
608		}
609	
610		if len(matches) == 0 {
611			if hasMeta {
612				caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
613				return nil, nil, nil
614			}
615			return nil, nil, p.Errf("File to import not found: %s", importPattern)
616		}
617		matches = skipDotfiles(globPattern, matches)
618	
619		var importedTokens []Token
620		for _, importFile := range matches {
621			newTokens, err := p.readImportFile(tree, importFile)
622			if err != nil {
623				return nil, nil, err
624			}
625			importedTokens = append(importedTokens, newTokens...)
626		}
627		return importedTokens, matches, nil
628	}
629	
630	// resolveDiskImports preserves the on-disk behavior: patterns are
631	// resolved relative to the importing token's file (issue #867),
632	// globs are bounded against pathological expansion (issue #2096),
633	// and dotfiles are skipped for directory-star globs (issue #5295).
634	func (p *parser) resolveDiskImports(importPattern string) ([]Token, []string, error) {
635		// make path relative to the file of the _token_ being processed rather
636		// than current working directory (issue #867) and then use glob to get
637		// list of matching filenames
638		absFile, err := caddy.FastAbs(p.Dispenser.File())
639		if err != nil {
640			return nil, nil, p.Errf("Failed to get absolute path of file: %s: %v", p.Dispenser.File(), err)
641		}
642	
643		var matches []string
644		var globPattern string
645		if !filepath.IsAbs(importPattern) {
646			globPattern = filepath.Join(filepath.Dir(absFile), importPattern)
647		} else {
648			globPattern = importPattern
649		}
650		if strings.Count(globPattern, "*") > 1 || strings.Count(globPattern, "?") > 1 ||
651			(strings.Contains(globPattern, "[") && strings.Contains(globPattern, "]")) {
652			// See issue #2096 - a pattern with many glob expansions can hang for too long
653			return nil, nil, p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
654		}
655		matches, err = filepath.Glob(globPattern)
656		if err != nil {
657			return nil, nil, p.Errf("Failed to use import pattern %s: %v", importPattern, err)
658		}
659		if len(matches) == 0 {
660			if strings.ContainsAny(globPattern, "*?[]") {
661				caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
662				return nil, nil, nil
663			}
664			return nil, nil, p.Errf("File to import not found: %s", importPattern)
665		}
666		matches = skipDotfiles(globPattern, matches)
667	
668		var importedTokens []Token
669		for _, importFile := range matches {
670			newTokens, err := p.readImportFile(diskSource{}, importFile)
671			if err != nil {
672				return nil, nil, err
673			}
674			importedTokens = append(importedTokens, newTokens...)
675		}
676		return importedTokens, matches, nil
677	}
678	
679	// skipDotfiles drops dotfile matches when the final pattern segment
680	// is a bare star, mirroring the historical glob behavior.
681	func skipDotfiles(globPattern string, matches []string) []string {
682		sep := "/"
683		if strings.Contains(globPattern, string(filepath.Separator)) {
684			sep = string(filepath.Separator)
685		}
686		segGlobPattern := strings.Split(globPattern, sep)
687		if !strings.HasPrefix(segGlobPattern[len(segGlobPattern)-1], "*") {
688			return matches
689		}
690		var filtered []string
691		for _, m := range matches {
692			seg := strings.Split(m, sep)
693			if strings.HasPrefix(seg[len(seg)-1], ".") {
694				continue
695			}
696			filtered = append(filtered, m)
697		}
698		return filtered
699	}
700	
701	// readImportFile lexes the individual file identified by importFile
702	// through src and returns its tokens. Token file names are normalized
703	// to stable paths: the absolute on-disk path when reading disk (issue
704	// #1892), and the normalized virtual path inside a FileTree, neither
705	// of which depends on the working directory.
706	func (p *parser) readImportFile(src importSource, importFile string) ([]Token, error) {
707		input, err := src.readFile(importFile)
708		if err != nil {
709			if errors.Is(err, errImportIsDir) {
710				return nil, p.Errf("Could not import %s: is a directory", importFile)
711			}
712			return nil, p.Errf("Could not import %s: %v", importFile, err)
713		}
714	
715		// only warning in case of empty files
716		if len(input) == 0 || len(strings.TrimSpace(string(input))) == 0 {
717			caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
718			return []Token{}, nil
719		}
720	
721		importedTokens, err := allTokens(importFile, input)
722		if err != nil {
723			return nil, p.Errf("Could not read tokens while importing %s: %v", importFile, err)
724		}
725	
726		filename := importFile
727		if _, isTree := src.(normalizedTree); !isTree {
728			// Tack the absolute path onto these tokens on disk so errors
729			// show the imported file's name reliably (issue #1892)
730			absName, absErr := caddy.FastAbs(importFile)
731			if absErr != nil {
732				return nil, p.Errf("Failed to get absolute path of file: %s: %v", importFile, absErr)
733			}
734			filename = absName
735		}
736		for i := range importedTokens {
737			importedTokens[i].File = filename
738		}
739	
740		return importedTokens, nil
741	}
742	
743	// directive collects tokens until the directive's scope
744	// closes (either end of line or end of curly brace block).
745	// It expects the currently-loaded token to be a directive
746	// (or } that ends a server block). The collected tokens
747	// are loaded into the current server block for later use
748	// by directive setup functions.
749	func (p *parser) directive() error {
750		// a segment is a list of tokens associated with this directive
751		var segment Segment
752	
753		// the directive itself is appended as a relevant token
754		segment = append(segment, p.Token())
755	
756		for p.Next() {
757			if p.Val() == "{" {
758				p.nesting++
759				if !p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
760					return p.Err("Unexpected next token after '{' on same line")
761				}
762				if p.isNewLine() {
763					return p.Err("Unexpected '{' on a new line; did you mean to place the '{' on the previous line?")
764				}
765			} else if p.Val() == "{}" {
766				if p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
767					return p.Err("Unexpected '{}' at end of line")
768				}
769			} else if p.isNewLine() && p.nesting == 0 {
770				p.cursor-- // read too far
771				break
772			} else if p.Val() == "}" && p.nesting > 0 {
773				p.nesting--
774			} else if p.Val() == "}" && p.nesting == 0 {
775				return p.Err("Unexpected '}' because no matching opening brace")
776			} else if p.Val() == "import" && p.isNewLine() {
777				if err := p.doImport(1); err != nil {
778					return err
779				}
780				p.cursor-- // cursor is advanced when we continue, so roll back one more
781				continue
782			}
783	
784			segment = append(segment, p.Token())
785		}
786	
787		p.block.Segments = append(p.block.Segments, segment)
788	
789		if p.nesting > 0 {
790			return p.EOFErr()
791		}
792	
793		return nil
794	}
795	
796	// openCurlyBrace expects the current token to be an
797	// opening curly brace. This acts like an assertion
798	// because it returns an error if the token is not
799	// an opening curly brace. It does NOT advance the token.
800	func (p *parser) openCurlyBrace() error {
801		if p.Val() != "{" {
802			if p.valLooksLikeGlobalOptionsAfterImportedSnippets() {
803				return p.Err("global options block must appear before import directives; move the global options block to the top of the Caddyfile")
804			}
805			return p.SyntaxErr("{")
806		}
807		return nil
808	}
809	
810	func (p *parser) valLooksLikeGlobalOptionsAfterImportedSnippets() bool {
811		if p.Val() != "import" || len(p.block.Keys) == 0 {
812			return false
813		}
814	
815		for _, key := range p.block.Keys {
816			if !strings.HasPrefix(key.Text, "(") || !strings.HasSuffix(key.Text, ")") {
817				return false
818			}
819		}
820	
821		return true
822	}
823	
824	// closeCurlyBrace expects the current token to be
825	// a closing curly brace. This acts like an assertion
826	// because it returns an error if the token is not
827	// a closing curly brace. It does NOT advance the token.
828	func (p *parser) closeCurlyBrace() error {
829		if p.Val() != "}" {
830			return p.SyntaxErr("}")
831		}
832		return nil
833	}
834	
835	func (p *parser) isNamedRoute() (bool, string) {
836		keys := p.block.Keys
837		// A named route block is a single key with parens, prefixed with &.
838		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "&(") && strings.HasSuffix(keys[0].Text, ")") {
839			return true, strings.TrimSuffix(keys[0].Text[2:], ")")
840		}
841		return false, ""
842	}
843	
844	func (p *parser) isSnippet() (bool, string) {
845		keys := p.block.Keys
846		// A snippet block is a single key with parens. Nothing else qualifies.
847		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "(") && strings.HasSuffix(keys[0].Text, ")") {
848			return true, strings.TrimSuffix(keys[0].Text[1:], ")")
849		}
850		return false, ""
851	}
852	
853	// read and store everything in a block for later replay.
854	func (p *parser) blockTokens(retainCurlies bool) ([]Token, error) {
855		// block must have curlies.
856		err := p.openCurlyBrace()
857		if err != nil {
858			return nil, err
859		}
860		nesting := 1 // count our own nesting
861		tokens := []Token{}
862		if retainCurlies {
863			tokens = append(tokens, p.Token())
864		}
865		for p.Next() {
866			if p.Val() == "}" {
867				nesting--
868				if nesting == 0 {
869					if retainCurlies {
870						tokens = append(tokens, p.Token())
871					}
872					break
873				}
874			}
875			if p.Val() == "{" {
876				nesting++
877			}
878			tokens = append(tokens, p.tokens[p.cursor])
879		}
880		// make sure we're matched up
881		if nesting != 0 {
882			return nil, p.SyntaxErr("}")
883		}
884		return tokens, nil
885	}
886	
887	// ServerBlock associates any number of keys from the
888	// head of the server block with tokens, which are
889	// grouped by segments.
890	type ServerBlock struct {
891		HasBraces    bool
892		Keys         []Token
893		Segments     []Segment
894		IsNamedRoute bool
895	}
896	
897	func (sb ServerBlock) GetKeysText() []string {
898		res := make([]string, 0, len(sb.Keys))
899		for _, k := range sb.Keys {
900			res = append(res, k.Text)
901		}
902		return res
903	}
904	
905	// DispenseDirective returns a dispenser that contains
906	// all the tokens in the server block.
907	func (sb ServerBlock) DispenseDirective(dir string) *Dispenser {
908		var tokens []Token
909		for _, seg := range sb.Segments {
910			if len(seg) > 0 && seg[0].Text == dir {
911				tokens = append(tokens, seg...)
912			}
913		}
914		return NewDispenser(tokens)
915	}
916	
917	// Segment is a list of tokens which begins with a directive
918	// and ends at the end of the directive (either at the end of
919	// the line, or at the end of a block it opens).
920	type Segment []Token
921	
922	// Directive returns the directive name for the segment.
923	// The directive name is the text of the first token.
924	func (s Segment) Directive() string {
925		if len(s) > 0 {
926			return s[0].Text
927		}
928		return ""
929	}
930	
931	// spanOpen and spanClose are used to bound spans that
932	// contain the name of an environment variable.
933	var (
934		spanOpen, spanClose    = []byte{'{', '$'}, []byte{'}'}
935		envVarDefaultDelimiter = ":"
936	)
937

