15	package caddyfile
16	
17	import (
18		"fmt"
19		"strconv"
20		"strings"
21	)
22	
23	// argsPlaceholder kinds recognized by the import expansion.
24	type argsPlaceholderKind int
25	
26	const (
27		argsSingle   argsPlaceholderKind = iota // {args[N]} (or deprecated {args.N})
28		argsVariadic                            // {args[a:b]}
29	)
30	
31	// argsPlaceholder describes a parsed argument placeholder.
32	type argsPlaceholder struct {
33		kind       argsPlaceholderKind
34		start      int // inclusive start index (variadic and single)
35		end        int // exclusive end index (variadic only)
36		deprecated bool
37	}
38	
39	// parseArgsPlaceholder parses body, the text between the braces of a
40	// placeholder (for example "args[0]" or "args[1:3]"), and reports
41	// whether it is a well-formed argument placeholder. A body that is
42	// clearly meant to be one but has an illegal index is reported with
43	// ok == true and a non-nil err, so callers can reject the parse
44	// instead of silently leaving the text untouched.
45	func parseArgsPlaceholder(body string) (argsPlaceholder, bool, error) {
46		if strings.HasPrefix(body, "args[") && strings.HasSuffix(body, "]") {
47			inner := body[len("args[") : len(body)-len("]")]
48			if inner == "" {
49				return argsPlaceholder{}, true, fmt.Errorf("placeholder {args[]} cannot have an empty index")
50			}
51	
52			rawStart, rawEnd, hasRange := strings.Cut(inner, ":")
53			if !hasRange {
54				index, err := parsePlaceholderIndex(rawStart)
55				if err != nil {
56					return argsPlaceholder{kind: argsSingle}, true, err
57				}
58				return argsPlaceholder{kind: argsSingle, start: index, end: index + 1}, true, nil
59			}
60	
61			// more than one colon is never a valid range
62			if strings.Count(inner, ":") > 1 {
63				return argsPlaceholder{kind: argsVariadic}, true, fmt.Errorf("variadic placeholder {%s} has an invalid index range", body)
64			}
65	
66			ph := argsPlaceholder{kind: argsVariadic}
67			if rawStart == "" {
68				ph.start = 0
69			} else {
70				index, err := parsePlaceholderIndex(rawStart)
71				if err != nil {
72					return argsPlaceholder{kind: argsVariadic}, true, err
73				}
74				ph.start = index
75			}
76			if rawEnd == "" {
77				// open-ended ranges are bounded by the argument count later
78				ph.end = -1
79			} else {
80				index, err := parsePlaceholderIndex(rawEnd)
81				if err != nil {
82					return argsPlaceholder{kind: argsVariadic}, true, err
83				}
84				ph.end = index
85			}
86			return ph, true, nil
87		}
88	
89		// TODO: Remove the deprecated {args.*} placeholder support at
90		// some point in the future.
91		if strings.HasPrefix(body, "args.") && body != "args." {
92			index, err := parsePlaceholderIndex(strings.TrimPrefix(body, "args."))
93			if err != nil {
94				return argsPlaceholder{deprecated: true}, true, err
95			}
96			return argsPlaceholder{kind: argsSingle, start: index, end: index + 1, deprecated: true}, true, nil
97		}
98	
99		return argsPlaceholder{}, false, nil
100	}
101	
102	// parsePlaceholderIndex parses a single non-negative argument index.
103	func parsePlaceholderIndex(raw string) (int, error) {
104		index, err := strconv.Atoi(raw)
105		if err != nil || index < 0 {
106			return 0, fmt.Errorf("invalid argument index %q", raw)
107		}
108		return index, nil
109	}
110	
111	// looksLikeArgsPlaceholder reports whether body, the contents of a
112	// brace pair, was clearly intended as an argument placeholder but is
113	// malformed. Such text is an error instead of being kept verbatim.
114	func looksLikeArgsPlaceholder(body string) bool {
115		return body == "args" || body == "args." ||
116			strings.HasPrefix(body, "args[") || strings.HasPrefix(body, "args.")
117	}
118	
119	// wholeTokenPlaceholder parses text expecting it to contain exactly
120	// one argument placeholder and nothing else. A token made of several
121	// adjacent (or malformed) placeholders is not a whole-token match; the
122	// slow-path scanner decides its fate instead.
123	func wholeTokenPlaceholder(text string) (argsPlaceholder, bool, error) {
124		if len(text) < 2 || text[0] != '{' || text[len(text)-1] != '}' {
125			return argsPlaceholder{}, false, nil
126		}
127		body := text[1 : len(text)-1]
128		// one placeholder cannot itself contain braces, so a token
129		// holding several adjacent placeholders is never a whole match
130		// and is left for the scanner
131		if strings.ContainsAny(body, "{}") {
132			return argsPlaceholder{}, false, nil
133		}
134		ph, ok, err := parseArgsPlaceholder(body)
135		if !ok {
136			return argsPlaceholder{}, false, nil
137		}
138		return ph, true, err
139	}
140	
141	// substituteImportArgs expands argument placeholders in one imported
142	// token. A whole-token placeholder is replaced with the argument
143	// token itself (so arguments containing spaces or quotes stay a
144	// single token, with their quoting intact); a placeholder embedded
145	// in surrounding text is substituted in place and can never cause
146	// re-tokenization.
147	//
148	// Ordinary braces, adjacent literal text, and braces escaped with a
149	// backslash are preserved verbatim. Malformed placeholders, indices
150	// out of range, and variadic placeholders embedded in other text are
151	// reported as errors, located at the imported token.
152	func substituteImportArgs(token Token, argTokens []Token) ([]Token, error) {
153		text := token.Text
154	
155		// fast path: the token is a single placeholder on its own
156		if ph, ok, err := wholeTokenPlaceholder(text); ok {
157			if err != nil {
158				return nil, importArgsErr(token, err.Error())
159			}
160			if ph.kind == argsSingle {
161				if ph.start >= len(argTokens) {
162					return nil, importArgsErr(token,
163						fmt.Sprintf("placeholder {args[%d]} is out of range: only %d argument(s) were given to the import", ph.start, len(argTokens)))
164				}
165				return []Token{positionArgToken(argTokens[ph.start], token)}, nil
166			}
167	
168			// variadic: validate the range against the available args
169			start, end, err := boundVariadic(ph, len(argTokens), text)
170			if err != nil {
171				return nil, importArgsErr(token, err.Error())
172			}
173			out := make([]Token, 0, end-start)
174			for _, arg := range argTokens[start:end] {
175				out = append(out, positionArgToken(arg, token))
176			}
177			return out, nil
178		}
179	
180		// slow path: scan the token for embedded placeholders
181		var sb strings.Builder
182		sb.Grow(len(text))
183		for i := 0; i < len(text); {
184			// escaped braces are literal braces; the escaping backslash
185			// is consumed so the brace is never re-expanded
186			if text[i] == '\\' && i+1 < len(text) && (text[i+1] == '{' || text[i+1] == '}') {
187				sb.WriteByte(text[i+1])
188				i += 2
189				continue
190			}
191	
192			if text[i] != '{' {
193				sb.WriteByte(text[i])
194				i++
195				continue
196			}
197	
198			closeRel := strings.IndexByte(text[i+1:], '}')
199			if closeRel < 0 {
200				// unmatched opening brace: the rest is ordinary text
201				sb.WriteString(text[i:])
202				break
203			}
204			end := i + 1 + closeRel
205			body := text[i+1 : end]
206	
207			ph, isArgs, parseErr := parseArgsPlaceholder(body)
208			if !isArgs {
209				if looksLikeArgsPlaceholder(body) {
210					return nil, importArgsErr(token, fmt.Sprintf("invalid argument placeholder {%s}", body))
211				}
212				// this brace pair is not an args placeholder (for
213				// example a JSON object), but an args placeholder may
214				// still be nested inside it; emit just the opening
215				// brace and rescan its contents
216				sb.WriteByte('{')
217				i++
218				continue
219			}
220			if parseErr != nil {
221				return nil, importArgsErr(token, parseErr.Error())
222			}
223			if ph.kind == argsVariadic {
224				return nil, importArgsErr(token, fmt.Sprintf("variadic placeholder {%s} must be a token on its own", body))
225			}
226			if ph.start >= len(argTokens) {
227				indexText := strconv.Itoa(ph.start)
228				if ph.deprecated {
229					return nil, importArgsErr(token,
230						fmt.Sprintf("placeholder {args.%s} is out of range: only %d argument(s) were given to the import", indexText, len(argTokens)))
231				}
232				return nil, importArgsErr(token,
233					fmt.Sprintf("placeholder {args[%s]} is out of range: only %d argument(s) were given to the import", indexText, len(argTokens)))
234			}
235	
236			// substitute only the argument's text, in place; quoting
237			// belongs to the surrounding token and is left untouched
238			sb.WriteString(argTokens[ph.start].Text)
239			i = end + 1
240		}
241	
242		out := token
243		out.Text = sb.String()
244		return []Token{out}, nil
245	}
246	
247	// boundVariadic resolves an open-ended variadic range and validates
248	// it against the number of available arguments.
249	func boundVariadic(ph argsPlaceholder, argCount int, text string) (int, int, error) {
250		start := ph.start
251		end := ph.end
252		if end == -1 {
253			end = argCount
254		}
255		if start > end {
256			return 0, 0, fmt.Errorf("variadic placeholder %s has a start index greater than its end index", text)
257		}
258		if end > argCount {
259			return 0, 0, fmt.Errorf("variadic placeholder %s is out of range: only %d argument(s) were given to the import", text, argCount)
260		}
261		return start, end, nil
262	}
263	
264	// positionArgToken returns a copy of a placeholder token carrying an
265	// argument's value. Location and import provenance stay attached to
266	// where the placeholder was written (so line adjacency and error
267	// locations are stable through nested imports), while the argument's
268	// exact text and quoting are preserved without re-tokenization.
269	func positionArgToken(arg, placeholder Token) Token {
270		t := placeholder.Clone()
271		t.Text = arg.Text
272		t.wasQuoted = arg.wasQuoted
273		t.quoteClosed = arg.quoteClosed
274		t.heredocMarker = arg.heredocMarker
275		return t
276	}
277	
278	// importArgsErr builds a parse error for a placeholder problem,
279	// pointing at the file and line where the placeholder was written.
280	func importArgsErr(token Token, msg string) error {
281		if len(token.imports) > 0 {
282			return fmt.Errorf("%s, at %s:%d import chain ['%s']",
283				msg, token.File, token.Line, strings.Join(token.imports, "','"))
284		}
285		return fmt.Errorf("%s, at %s:%d", msg, token.File, token.Line)
286	}
287	
288	// parseVariadic determines if the token is a variadic placeholder,
289	// and if so, determines the index range (start/end) of args to use.
290	// Returns a boolean signaling whether a variadic placeholder was found,
291	// and the start and end indices.
292	//
293	// Deprecated: retained for the unit-level predicate checks; expansion
294	// goes through substituteImportArgs, which also rejects malformed
295	// placeholders and out-of-range indices as hard parse errors.
296	func parseVariadic(token Token, argCount int) (bool, int, int) {
297		ph, ok, err := wholeTokenPlaceholder(token.Text)
298		if err != nil || !ok || ph.kind != argsVariadic {
299			return false, 0, 0
300		}
301		start, end, err := boundVariadic(ph, argCount, token.Text)
302		if err != nil {
303			return false, 0, 0
304		}
305		return true, start, end
306	}
