26	// flattenBlocks renders the parsed blocks as a sequence of
27	// "directive|arg|arg" lines: the directive order and exact argument
28	// bytes are the only observation surface these tests rely on.
29	func flattenBlocks(blocks []ServerBlock) [][]string {
30		var out [][]string
31		for _, b := range blocks {
32			for _, seg := range b.Segments {
33				var line []string
34				for _, tok := range seg {
35					line = append(line, tok.Text)
36				}
37				out = append(out, line)
38			}
39		}
40		return out
41	}
