231		}{
232			{"insufficient args", "d {args[2]}\n", "out of range"},
233			{"non-numeric index", "d {args[x]}\n", "invalid argument"},
234			{"negative index", "d {args[-1]}\n", "invalid argument"},
235			{"empty index", "d {args[]}\n", "empty index"},
236			{"inverted range", "d {args[2:1]}\n", "start index greater than its end index"},
237			{"range too far", "d {args[0:5]}\n", "out of range"},
238			{"embedded variadic", "d x{args[:]}y\n", "must be a token on its own"},
