package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"reflect"
	"strings"
	"sync"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

func flat(bs []caddyfile.ServerBlock) [][]string {
	out := [][]string{}
	for _, b := range bs {
		for _, seg := range b.Segments {
			row := []string{}
			for _, tok := range seg {
				row = append(row, tok.Text)
			}
			out = append(out, row)
		}
	}
	return out
}

var failures int

func show(name string, tree caddyfile.FileTree, want [][]string, wantErr string) {
	bs, err := caddyfile.Parse("Caddyfile", tree["Caddyfile"], tree)
	got := flat(bs)
	encoded, _ := json.Marshal(got)
	if err != nil {
		fmt.Printf("%s error=%q parsed=%s\n", name, err.Error(), encoded)
	} else {
		fmt.Printf("%s parsed=%s\n", name, encoded)
	}
	if wantErr != "" {
		if err == nil {
			fmt.Printf("FAIL %s: expected error containing %q\n", name, wantErr)
			failures++
			return
		}
		if bs != nil {
			fmt.Printf("FAIL %s: failed parse returned non-nil blocks\n", name)
			failures++
		}
		if !strings.Contains(err.Error(), wantErr) {
			fmt.Printf("FAIL %s: error %q lacks %q\n", name, err.Error(), wantErr)
			failures++
		}
		return
	}
	if err != nil {
		fmt.Printf("FAIL %s: unexpected error: %v\n", name, err)
		failures++
		return
	}
	if !reflect.DeepEqual(got, want) {
		fmt.Printf("FAIL %s: expected %v, got %v\n", name, want, got)
		failures++
	}
}

func main() {
	// success cases (raw bytes, exactly as the harness intends)
	show("args-and-literals", caddyfile.FileTree{
		"Caddyfile": []byte("import f.caddy \"hello world\" \"\" \"a\\\"b\"\n"),
		"f.caddy":   []byte("a {args[0]}\nb {args[1]}\nc {args[2]}\njoin pre-{args[0]}-post\nplain {host}\nescaped \\{args[0]\\}\n"),
	}, [][]string{{"a", "hello world"}, {"b", ""}, {"c", "a\"b"}, {"join", "pre-hello world-post"}, {"plain", "{host}"}, {"escaped", "{args[0]}"}}, "")

	show("variadic", caddyfile.FileTree{
		"Caddyfile": []byte("import f.caddy one \"two words\" three\n"),
		"f.caddy":   []byte("all {args[:]}\ntail {args[1:]}\nspan {args[0:2]}\nadj {args[0]}:{args[1]}\n"),
	}, [][]string{{"all", "one", "two words", "three"}, {"tail", "two words", "three"}, {"span", "one", "two words"}, {"adj", "one:two words"}}, "")

	show("separator-normalization", caddyfile.FileTree{
		"Caddyfile":  []byte("import sub/f.caddy\n"),
		"sub\\f.caddy": []byte("separator value\n"),
	}, [][]string{{"separator", "value"}}, "")

	show("glob-order-and-repeat", caddyfile.FileTree{
		"Caddyfile":        []byte("import conf/*.caddy\nimport conf/a.caddy\n"),
		"conf/b.caddy":     []byte("from-b\n"),
		"conf/a.caddy":     []byte("from-a\n"),
		"conf/.hidden.caddy": []byte("hidden\n"),
	}, [][]string{{"from-a"}, {"from-b"}, {"from-a"}}, "")

	// error cases
	show("scope-without-redeclaration", caddyfile.FileTree{
		"Caddyfile":   []byte("import outer.caddy outer-value\n"),
		"outer.caddy": []byte("import inner.caddy\n"),
		"inner.caddy": []byte("inner {args[0]}\n"),
	}, nil, "inner.caddy:1")
	show("invalid-index", caddyfile.FileTree{
		"Caddyfile": []byte("import bad.caddy x\n"), "bad.caddy": []byte("d {args[x]}\n"),
	}, nil, "invalid argument")
	show("embedded-variadic", caddyfile.FileTree{
		"Caddyfile": []byte("import bad.caddy x\n"), "bad.caddy": []byte("d pre-{args[:]}-post\n"),
	}, nil, "must be a token on its own")
	show("unclosed-quote", caddyfile.FileTree{
		"Caddyfile": []byte("respond \"never closed"),
	}, nil, "unclosed quote")
	show("missing-target", caddyfile.FileTree{
		"Caddyfile": []byte("import missing.caddy\n"),
	}, nil, "missing.caddy")

	// error stability: same input twice -> identical error text;
	// and first failure must not poison a subsequent parse
	bad := caddyfile.FileTree{"Caddyfile": []byte("import f.caddy\n")}
	_, e1 := caddyfile.Parse("Caddyfile", bad["Caddyfile"], bad)
	_, e2 := caddyfile.Parse("Caddyfile", bad["Caddyfile"], bad)
	if e1 == nil || e1.Error() != e2.Error() {
		fmt.Printf("FAIL error-stability: %v vs %v\n", e1, e2)
		failures++
	}
	good := caddyfile.FileTree{"Caddyfile": []byte("import f.caddy\n"), "f.caddy": []byte("ok yes\n")}
	bs, err := caddyfile.Parse("Caddyfile", good["Caddyfile"], good)
	if err != nil || !reflect.DeepEqual(flat(bs), [][]string{{"ok", "yes"}}) {
		fmt.Printf("FAIL reparse-after-failure: %v %v\n", err, flat(bs))
		failures++
	}
	// same top-level filename, different static contents -> only this input
	other := caddyfile.FileTree{"Caddyfile": []byte("import f.caddy\n"), "f.caddy": []byte("ok no\n")}
	bs, err = caddyfile.Parse("Caddyfile", other["Caddyfile"], other)
	if err != nil || !reflect.DeepEqual(flat(bs), [][]string{{"ok", "no"}}) {
		fmt.Printf("FAIL distinct-input: %v %v\n", err, flat(bs))
		failures++
	}

	// cycle: error names files and is stable
	cyc := caddyfile.FileTree{
		"Caddyfile": []byte("import a.caddy\n"),
		"a.caddy":   []byte("import b.caddy\n"),
		"b.caddy":   []byte("import a.caddy\n"),
	}
	_, ce1 := caddyfile.Parse("Caddyfile", cyc["Caddyfile"], cyc)
	_, ce2 := caddyfile.Parse("Caddyfile", cyc["Caddyfile"], cyc)
	if ce1 == nil {
		fmt.Println("FAIL cycle: expected error")
		failures++
	} else if ce1.Error() != ce2.Error() {
		fmt.Printf("FAIL cycle stability: %q vs %q\n", ce1.Error(), ce2.Error())
		failures++
	} else {
		fmt.Printf("cycle error=%q\n", ce1.Error())
	}

	// no-match glob keeps success semantics; repeated determinism
	ng := caddyfile.FileTree{"Caddyfile": []byte(":80 {\n\timport nope/*.caddy\n\trespond hi\n}\n")}
	b1, err := caddyfile.Parse("Caddyfile", ng["Caddyfile"], ng)
	b2, _ := caddyfile.Parse("Caddyfile", ng["Caddyfile"], ng)
	if err != nil || !reflect.DeepEqual(flat(b1), flat(b2)) {
		fmt.Printf("FAIL no-match glob determinism: %v\n", err)
		failures++
	}

	// concurrent isolation
	var wg sync.WaitGroup
	errs := make(chan error, 8)
	for i := 0; i < 8; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			value := fmt.Sprintf("worker-%d", i)
			tree := caddyfile.FileTree{"Caddyfile": []byte("import f.caddy\n"), "f.caddy": []byte("value " + value + "\n")}
			bs, err := caddyfile.Parse("Caddyfile", tree["Caddyfile"], tree)
			got := flat(bs)
			if err != nil {
				errs <- err
				return
			}
			if len(got) != 1 || len(got[0]) != 2 || got[0][1] != value {
				errs <- fmt.Errorf("parallel-%d observed %v", i, got)
			}
		}(i)
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		fmt.Println("FAIL parallel:", err)
		failures++
	}

	if failures > 0 {
		fmt.Printf("\n%d FAILURES\n", failures)
		os.Exit(1)
	}
	_ = errors.New
	fmt.Println("\nALL ACCEPTANCE CASES PASSED")
}
EOF
