// cycle error is stable and names a closed loop; a failing parse
// returns no blocks; a second call with different contents is clean.
func TestZZFinalCycleAndReparse(t *testing.T) {
	cyc := FileTree{
		"Caddyfile": []byte("import a.caddy\n"),
		"a.caddy":   []byte("import b.caddy\n"),
		"b.caddy":   []byte("import a.caddy\n"),
	}
	b1, e1 := Parse("Caddyfile", cyc["Caddyfile"], cyc)
	_, e2 := Parse("Caddyfile", cyc["Caddyfile"], cyc)
	if e1 == nil || b1 != nil {
		t.Fatalf("cycle must fail with nil blocks, got %v %v", b1, e1)
	}
	if e1.Error() != e2.Error() || !strings.Contains(e1.Error(), "cycle") {
		t.Fatalf("unstable cycle error: %q vs %q", e1, e2)
	}

	// dot/dotdot cleaning relative to declaring file
	tree := FileTree{
		"Caddyfile": []byte("import sub/./f.caddy\n"),
		"sub/f.caddy": []byte("import ../g.caddy\n"),
		"g.caddy":     []byte("d v\n"),
	}
	lines, err := func() ([][]string, error) {
		bs, err := Parse("Caddyfile", tree["Caddyfile"], tree)
		return flattenBlocks(bs), err
	}()
	if err != nil || len(lines) != 1 || lines[0][0] != "d" || lines[0][1] != "v" {
		t.Fatalf("dot/dotdot resolution wrong: %v %v", lines, err)
	}
}
EOF
